### CREATE `apps/graph-manager/src/server/internal-listener.ts`

- **IMPLEMENT**: the loopback plain-HTTP listener for the terminals' internal API when the main server is HTTPS.
  ```typescript
  import http from "node:http";
  import type { AddressInfo } from "node:net";
  import type { FastifyInstance } from "fastify";

  /**
   * A plain-HTTP server on 127.0.0.1 (random port) that hands `/api/internal/*` requests to the app's router and answers
   * every other path 404. Used when graph-manager serves HTTPS: the terminals' tools (shim.ts, mcp.ts) call
   * GM_INTERNAL_URL with Node's fetch, which can't skip certificate checks on loopback.
   */
  export async function startInternalListener(app: FastifyInstance): Promise<{ url: string; close(): Promise<void> }> {
    const server = http.createServer((req, res) => {
      if (!(req.url ?? "").startsWith("/api/internal/")) {
        res.statusCode = 404;
        res.setHeader("content-type", "application/json");
        res.end(JSON.stringify({ error: "not found" }));
        return;
      }
      app.routing(req, res);
    });
    await new Promise<void>((resolve, reject) => {
      server.once("error", reject);
      server.listen(0, "127.0.0.1", () => resolve());
    });
    const { port } = server.address() as AddressInfo;
    return { url: `http://127.0.0.1:${port}`, close: () => new Promise<void>((resolve) => server.close(() => resolve())) };
  }
  ```
- **GOTCHA**: `app.routing(req, res)` is Fastify's public router entry (`fastify/types/instance.d.ts:184`); it runs the full lifecycle, including the auth `onRequest` hook (which already exempts `/api/internal/*`, `auth.ts:64`; those routes check their own bearer token). It needs `await app.ready()` first — call it from an `onListen` hook (the app is ready then). Call `server.closeAllConnections?.()` before `close` if keep-alive sockets keep it open.
- **VALIDATE**: `npm run typecheck -w graph-manager`

